using System;using System.Collections.Generic;using System.Drawing;using System.Linq;using System.Reflection;using System.Threading;using System.Windows.Forms;using System.IO;using System.Runtime.Serialization.Json;
namespace Frociart.Tests {
 sealed class PolicyCanvas:FlowCanvas{protected override Keys GetInteractionModifiers(){return Keys.None;}protected override void OnLostFocus(EventArgs e){}protected override void OnMouseCaptureChanged(EventArgs e){}internal void Down(Point p){OnMouseDown(new MouseEventArgs(MouseButtons.Left,1,p.X,p.Y,0));Capture=false;}internal void MoveTo(Point p){OnMouseMove(new MouseEventArgs(MouseButtons.Left,1,p.X,p.Y,0));}internal void Up(Point p){OnMouseUp(new MouseEventArgs(MouseButtons.Left,1,p.X,p.Y,0));}}
 sealed class PolicyHost:Form{protected override bool ShowWithoutActivation{get{return true;}}}
 static class DecisionPeelTests {
 static int checks;static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;static Stack<Diagram> undo=new Stack<Diagram>();
 static void Check(bool b,string t){if(!b)throw new Exception(t);checks++;Console.WriteLine("PASS "+t);}
 static object Get(object o,string n){for(var t=o.GetType();t!=null;t=t.BaseType){var f=t.GetField(n,F);if(f!=null)return f.GetValue(o);}throw new Exception(n);}
 static object Call(object o,string n,params object[] a){for(var t=o.GetType();t!=null;t=t.BaseType){var m=t.GetMethods(F).FirstOrDefault(x=>x.Name==n&&x.GetParameters().Length==a.Length);if(m!=null)return m.Invoke(o,a);}throw new Exception(n);}
 static void Pump(int ms=40){var end=DateTime.UtcNow.AddMilliseconds(ms);do{Application.DoEvents();Thread.Sleep(2);}while(DateTime.UtcNow<end);}
 static string Bytes(Diagram d){using(var m=new MemoryStream()){new DataContractJsonSerializer(typeof(Diagram)).WriteObject(m,d);return Convert.ToBase64String(m.ToArray());}}
 static void Reset(PolicyCanvas c,int mode=0){var d=Examples.Parity();if(mode==1)foreach(var e in d.Edges.Where(e=>e.From=="check"))e.To="even";if(mode==2)d.Edges.RemoveAll(e=>e.From=="check"&&e.Branch=="false");d.Nodes.Add(new FlowNode{Id="process",Kind=NodeKind.Process,X=900,Y=300,Text="x = 1"});d.Nodes.Add(new FlowNode{Id="fresh",Kind=NodeKind.Start,X=1100,Y=100,Text="Inizio"});d.Nodes.Add(new FlowNode{Id="freshEnd",Kind=NodeKind.End,X=1100,Y=600,Text="Fine"});d.Edges.Add(new FlowEdge{Id="drop",From="fresh",To="freshEnd"});c.Diagram=d;c.SnapToGrid=false;c.FitToView();undo.Clear();Pump(400);}
 static Point At(PolicyCanvas c,string id){var n=c.Diagram.Nodes.First(x=>x.Id==id);var b=FlowCanvas.GetNodeBounds(n);return Point.Round(c.WorldToClient(new PointF(b.X+b.Width/2,b.Y+b.Height/2)));}
 static void Undo(PolicyCanvas c,string original){Check(undo.Count==1,"Gesture creates exactly one Undo");c.Diagram=undo.Pop();Pump(400);Check(Bytes(c.Diagram)==original,"Undo restores complete exact document");}
 static IEnumerable<Control> Walk(Control c){yield return c;foreach(Control v in c.Controls)foreach(var x in Walk(v))yield return x;}
 static int Release(PolicyCanvas c,Point p,string choice=null,Action<BranchContinuationDialog> inspect=null){int dialogs=0;using(var timer=new System.Windows.Forms.Timer{Interval=10}){timer.Tick+=(s,e)=>{var d=Application.OpenForms.OfType<BranchContinuationDialog>().FirstOrDefault();if(d==null)return;dialogs++;timer.Stop();if(inspect!=null)inspect(d);if(choice=="X"||choice==null)d.Close();else ((Button)Walk(d).First(x=>x is Button&&x.Text==choice)).PerformClick();};timer.Start();c.Up(p);}return dialogs;}
 [STAThread]static int Main(){try{Application.EnableVisualStyles();UiMotion.SetEnabled(true);Ui.SetDarkMode(true,false);using(var f=new PolicyHost{ClientSize=new Size(1200,900),ShowInTaskbar=false,Location=new Point(-4000,-3000),StartPosition=FormStartPosition.Manual})using(var c=new PolicyCanvas{Dock=DockStyle.Fill}){f.Controls.Add(c);f.Show();c.DiagramChanging+=(s,e)=>undo.Push(DiagramIO.Clone(c.Diagram));
 foreach(int mode in new[]{0,1,2}){Reset(c,mode);var original=Bytes(c.Diagram);var ids=c.Diagram.Nodes.Select(n=>n.Id).ToArray();var p=At(c,"check");c.Down(p);Pump(1800);Check((bool)Get(c,mode==0?"stickerAmbiguous":"stickerDetached"),"Decision reaches detached preview for topology "+mode);var blank=new Point(p.X+190,p.Y-80);c.MoveTo(blank);Check(Release(c,blank)==0,"Blank decision release never opens a menu");Check(c.Diagram.Nodes.Select(n=>n.Id).SequenceEqual(ids)&&!c.Diagram.Edges.Any(e=>e.From=="check"||e.To=="check"),"Blank release really detaches and preserves every branch block");if(mode==0)Check(!c.Diagram.Edges.Any(e=>e.From=="input"),"Distinct previous branches are left free without choosing arbitrarily");Undo(c,original);}
 foreach(string choice in new[]{"X","Sì","Nessuno","Annulla inserimento"}){Reset(c);string original=Bytes(c.Diagram);var p=At(c,"check");c.Down(p);Pump(1800);var start=c.Diagram.Nodes.First(n=>n.Id=="fresh");var b=FlowCanvas.GetNodeBounds(start);var target=Point.Round(c.WorldToClient(new PointF(b.X+b.Width/2,400)));c.MoveTo(target);Check((bool)Get(c,"insertReady"),"A real new arrow is detected");var dropped=(RectangleF)Call(c,"DisplayBounds",c.Diagram.Nodes.First(n=>n.Id=="check"));int shown=Release(c,target,choice,d=>{Check(d.Text.StartsWith("Inserisci"),"Only new insertion chooser is shown");var displayed=(RectangleF)Call(c,"DisplayBounds",c.Diagram.Nodes.First(n=>n.Id=="check"));Check(Math.Abs(displayed.X-dropped.X)<1&&Math.Abs(displayed.Y-dropped.Y)<1,"Pending menu retains dropped visual pose");Check(Bytes(c.Diagram)==original,"Stored graph is unchanged while insertion is pending");});Check(shown==1,"Exactly one insertion menu opens");if(choice=="Annulla inserimento"){Check(Bytes(c.Diagram)==original&&undo.Count==0,"Explicit cancellation preserves original graph and history");continue;}var node=c.Diagram.Nodes.First(n=>n.Id=="check");if(choice=="X"){Check(!c.Diagram.Edges.Any(e=>e.From=="check"||e.To=="check")&&c.Diagram.Edges.Single(e=>e.Id=="drop").To=="freshEnd","X leaves decision free and target arrow intact");Check(Math.Abs(node.X-dropped.X)<1&&Math.Abs(node.Y-dropped.Y)<1,"X keeps exact dropped coordinates");}else Check(c.Diagram.Edges.Single(e=>e.Id=="drop").To=="check","Branch choice integrates the decision");Undo(c,original);}
 foreach(NodeKind kind in new[]{NodeKind.Process,NodeKind.Decision,NodeKind.Input,NodeKind.Output}){Reset(c);string id=c.Diagram.Nodes.First(n=>n.Kind==kind).Id,original=Bytes(c.Diagram);int count=c.Diagram.Nodes.Count;var p=At(c,id);c.Down(p);Pump(1800);Check((float)Get(c,"trashReveal")>.9f,"Completed peel reveals trash: "+kind);var box=(Rectangle)Call(c,"TrashBounds");var drop=new Point(box.X+box.Width/2,box.Y+box.Height/2);c.MoveTo(drop);Pump(50);Release(c,drop);Check(c.Diagram.Nodes.Count==count-1&&!c.Diagram.Nodes.Any(n=>n.Id==id)&&!c.Diagram.Edges.Any(e=>e.From==id||e.To==id),"Trash removes exactly one block and no dangling arrow: "+kind);Check(Get(c,"trashFlight")!=null,"Trash release starts an animated shrinking flight");Pump(420);Check(Get(c,"trashFlight")==null,"Trash flight settles and releases bitmap");Undo(c,original);}
 Reset(c);string keep=c.Diagram.Nodes.First(n=>n.Kind==NodeKind.Process).Id;var from=At(c,keep);var trash=(Rectangle)Call(c,"TrashBounds");c.Down(from);c.MoveTo(new Point(trash.X+trash.Width/2,trash.Y+trash.Height/2));Release(c,new Point(trash.X+trash.Width/2,trash.Y+trash.Height/2));Check(c.Diagram.Nodes.Any(n=>n.Id==keep),"An ordinary drag cannot delete through the peel-only trash target");f.Close();}
 Console.WriteLine("DECISION_PEEL_FINISHED checks="+checks+" errors=0");return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
 }
}
